import{_ as e,o as i,c as l,aw as t}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Информация","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/redux/main/info.md","filePath":"wiki/dev-commit/framework-react/redux/main/info.md"}'),r={name:"wiki/dev-commit/framework-react/redux/main/info.md"};function o(d,a,n,s,c,u){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://redux.js.org/" target="_blank" rel="noreferrer">https://redux.js.org/</a></p></div><h2 id="redux" tabindex="-1">Redux <a class="header-anchor" href="#redux" aria-label="Permalink to &quot;Redux&quot;">​</a></h2><ul><li><strong>Redux</strong> - это инструмент управления состоянием приложения (предсказуемый контейнер состояния для JS приложений). Он подходит для одностраничных приложений, в которых управление состоянием может со временем становиться сложным. Redux не связан с каким-то определенным фреймворком, и хотя разрабатывался для React, может использоваться с Angular или jQuery</li><li>Redux - отделение данных от представления</li><li>В React «однонаправленный поток данных» - поток данных проходит в одном направлении, от родителя к ребенку. При этом не очевидно, как два компонента, не связанные отношением родитель-ребенок, будут взаимодействовать между собой</li><li>Redux предлагает хранить все состояние приложения в одном месте, называемом «store» («хранилище»). Компоненты «отправляют» изменение состояния в хранилище, а не напрямую другим компонентам. Компоненты, которые должны быть в курсе этих изменений, «подписываются» на хранилище</li></ul><h3 id="принципы" tabindex="-1">Принципы <a class="header-anchor" href="#принципы" aria-label="Permalink to &quot;Принципы&quot;">​</a></h3><ol><li>Единственный источник истины</li><li>Состояние доступно только для чтения</li><li>Изменения делаются «чистыми» функциями</li></ol><h2 id="однонаправленныи-поток-данных" tabindex="-1">Однонаправленный поток данных <a class="header-anchor" href="#однонаправленныи-поток-данных" aria-label="Permalink to &quot;Однонаправленный поток данных&quot;">​</a></h2><ol><li>Приложение получило начальное состояние (initial state)</li><li>Пользователь нажав кнопку, отправил действие (dispatch action)</li><li>Соответсвующий редьюсер обновил часть приложения, в согласии с тем, что узнал от действия</li><li>Приложение изменилось и теперь отражает новое состояние</li><li>... (все повторяется по кругу, с пункта 2)</li></ol><h2 id="структура-фаилов" tabindex="-1">Структура файлов <a class="header-anchor" href="#структура-фаилов" aria-label="Permalink to &quot;Структура файлов&quot;">​</a></h2><ul><li>Rails Style</li><li>Redux Ducks</li></ul>',10)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
